// Vercel build: compiles both apps in web mode and writes them into
// ../api/_pages.js, which the /api/app function serves only after the
// ?key= check (so the pages are never public static files).
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { buildPage } from "./build.mjs";

const pages = {
  stock: await buildPage("warehouse", "倉庫存貨", { web: true }),
  groupbuy: await buildPage("groupbuy", "團購記錄", { web: true }),
};
writeFileSync(
  fileURLToPath(new URL("../api/_pages.js", import.meta.url)),
  "// Generated by artifacts/build-web.mjs — do not edit or commit.\nexport const PAGES = " + JSON.stringify(pages) + ";\n",
);
for (const [k, v] of Object.entries(pages)) console.log(k, (v.length / 1024).toFixed(0) + " KB");
